package dec.core.context.runtime;
import java.util.Objects;
/** P2 大小写敏感的 opaque runtime ID；值本身不携带任何 authority。 */
public final class RuntimeCollectionCursorId implements Comparable<RuntimeCollectionCursorId>{private final String value;private RuntimeCollectionCursorId(String value){this.value=requireValue(value);}public static RuntimeCollectionCursorId of(String value){return new RuntimeCollectionCursorId(value);}public String value(){return value;}@Override public int compareTo(RuntimeCollectionCursorId other){return value.compareTo(Objects.requireNonNull(other,"other").value);}@Override public boolean equals(Object other){return this==other||other instanceof RuntimeCollectionCursorId&&value.equals(((RuntimeCollectionCursorId)other).value);}@Override public int hashCode(){return value.hashCode();}@Override public String toString(){return value;}private static String requireValue(String raw){Objects.requireNonNull(raw,"value");if(raw.trim().isEmpty()||!raw.equals(raw.trim()))throw new IllegalArgumentException("value must be non-blank and trimmed");return raw;}}
